import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    index += 1

    blue = []
    red = []
    for _ in range(n - 1):
        b = int(data[index])
        index += 1
        r = int(data[index])
        index += 1
        blue.append(b)
        red.append(r)

    q = int(data[index])
    index += 1

    queries = []
    for _ in range(q):
        v = int(data[index])
        index += 1
        s = data[index]
        index += 1
        queries.append((v, s))

    # Initialize the graph
    graph = {}
    for i in range(n - 1):
        graph[i + 1] = {'blue': blue[i], 'red': red[i]}

    # Function to get the next state
    def next_state(current_state, v, s):
        new_state = current_state[:]
        new_state[v - 1] = 'R' if current_state[v - 1] == 'B' else 'B'
        next_v = graph[v]['blue'] if new_state[v - 1] == 'B' else graph[v]['red']
        return (next_v, new_state)

    # BFS to find the first occurrence of each state
    from collections import deque, defaultdict

    visited = defaultdict(lambda: -1)
    queue = deque([(1, ['B'] * (n - 1), 0)])
    visited[(1, tuple(['B'] * (n - 1)))] = 0

    while queue:
        v, state, time = queue.popleft()

        for v_query, s_query in queries:
            if v == v_query and tuple(state) == tuple(list(s_query)):
                print(time)
                break

        for v_query, s_query in queries:
            if v == v_query and tuple(state) == tuple(list(s_query)):
                break
        else:
            continue

        for i in range(n - 1):
            if state[i] == 'B':
                next_v = graph[i + 1]['blue']
                new_state = state[:]
                new_state[i] = 'R'
                if visited[(next_v, tuple(new_state))] == -1:
                    visited[(next_v, tuple(new_state))] = time + 1
                    queue.append((next_v, new_state, time + 1))
            else:
                next_v = graph[i + 1]['red']
                new_state = state[:]
                new_state[i] = 'B'
                if visited[(next_v, tuple(new_state))] == -1:
                    visited[(next_v, tuple(new_state))] = time + 1

                    queue.append((next_v, new_state, time + 1))

    for v_query, s_query in queries:
        if visited[(v_query, tuple(list(s_query)))] == -1:
            print(-1)

if __name__ == "__main__":
    main()
